using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;
public static class FinalZatodItemSources { public static object Run(){var scenes=Enumerable.Range(0,SceneManager.sceneCount).Select(i=>new{SceneManager.GetSceneAt(i).path,SceneManager.GetSceneAt(i).isDirty}).ToArray();if(EditorApplication.isPlaying||EditorApplication.isCompiling||scenes.Any(s=>s.isDirty))throw new Exception("Editor not clean");var result=new{Result="PASS",Playing=EditorApplication.isPlaying,Compiling=EditorApplication.isCompiling,Scenes=scenes};File.WriteAllText(Path.GetFullPath("../Artifacts/ZatodItemSourcesChecks/editor-final.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}}
